            for v, w in adj[u]:
                if dist[v] > dist[u] + w:
                    dist[v] = dist[u] + w
                    updated = True
        if not updated:
            break

    # Check for negative weight cycles that are reachable from s
    for u in range(n):
        if dist[u] == float('inf'):
            continue
        for v, w in adj[u]:
            if dist[v] > dist[u] + w:
                # If there's a negative cycle that is reachable from s, then t is unreachable
                if t in [v for v in range(n) if dist[v] != float('inf')]:
                    return -1

    return dist[t] if dist[t] != float('inf') else -1

