    if s == t:
        return 0

    # Build adjacency list
    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))

    # Dijkstra's algorithm to find shortest path from s to t
    dist = [float('inf')] * n
    dist[s] = 0
    visited = [False] * n
    pq = [(0, s)]

    while pq:
        current_dist, u = heapq.heappop(pq)
        if visited[u]:
            continue
        visited[u] = True
        for v, w in graph[u]:
            if dist[v] > current_dist + w:
                dist[v] = current_dist + w
                heapq.heappush(pq, (dist[v], v))

    return dist[t] if dist[t] != float('inf') else -1

