def avoid_ship(grid):
    import sys
    sys.setrecursionlimit(1000000)
    rows = len(grid)
    cols = len(grid[0])
    directions = [(-1,0),(1,0),(0,-1),(0,1)]

    def dfs(r, c):
        if r < 0 or r >= rows or c < 0 or c >= cols or grid[r][c] == '1':
            return
        grid[r][c] = '1'
        for dr, dc in directions:
            dfs(r + dr, c + dc)

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == '0':
                dfs(r, c)

