def is_valid_position(x, y):
    return 0 <= x < 8 and 0 <= y < 8

def knight_moves(x, y):
    moves = [
        (2, 1), (1, 2), (-1, 2), (-2, 1),
        (-2, -1), (-1, -2), (1, -2), (2, -1)
    ]
    return [(x + dx, y + dy) for dx, dy in moves]

def knight_ways(start, end, n):
    from collections import deque

    if start == end:
        return 1

    visited = [[False] * n for _ in range(n)]
    queue = deque()
    queue.append((start[0], start[1], 1))
    visited[start[0]][start[1]] = True

    while queue:
        x, y, steps = queue.popleft()
        for dx, dy in knight_moves(x, y):
            nx, ny = dx, dy
            if is_valid_position(nx, ny) and not visited[nx][ny]:
                if (nx, ny) == end:
                    return steps + 1
                visited[nx][ny] = True
                queue.append((nx, ny, steps + 1))

    return -1

class Solution:
    def shipWithinDays(self, weights: List[int], days: int) -> int:
        def can_ship(capacity):
            days_needed = 1
            current_capacity = 0
            for weight in weights:
                if current_capacity + weight > capacity:
                    days_needed += 1
                    current_capacity = 0
                current_capacity += weight
                if days_needed > days:
                    return False
            return True

        left = max(weights)
        right = sum(weights)
        while left < right:
            mid = (left + right) // 2
            if can_ship(mid):
                right = mid
            else:
                left = mid + 1
        return left

