def count_islands(grid):
    if not grid:
        return 0

    rows, cols = len(grid), len(grid[0])
    visited = [[False for _ in range(cols)] for _ in range(rows)]
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    def dfs(r, c):
        if r < 0 or r >= rows or c < 0 or c >= cols or grid[r][c] == 0 or visited[r][c]:
            return
        visited[r][c] = True
        for dr, dc in directions:
            dfs(r + dr, c + dc)

    island_count = 0
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1 and not visited[r][c]:
                dfs(r, c)
                island_count += 1

    return island_count

def distribute_cargo(cargo_weights, port_capacity):
    """
    Distribute cargo weights to ports with a given capacity.
    Returns a list indicating how many cargo items each port receives.
    Each port can hold up to `port_capacity` total weight.
    """
    num_ports = len(port_capacity)
    result = [0] * num_ports
    current_weight = 0

    for weight in cargo_weights:
        if current_weight + weight <= port_capacity[0]:
            result[0] += weight
            current_weight += weight
        else:
            # Find the next open port that can take the cargo
            for i in range(1, num_ports):
                if current_weight + weight <= port_capacity[i]:
                    result[i] += weight
                    current_weight += weight
                    break
            else:
                raise ValueError("No port available to take the cargo.")

    return result

