import random

class Environment:
    def __init__(self, size):
        self.size = size
        self.grid = [['.' for _ in range(size)] for _ in range(size)]
        self.player_pos = (0, 0)
        self.item_pos = (size - 1, size - 1)
        self.tool_pos = (size - 2, size - 1)
        self.grid[self.player_pos[0]][self.player_pos[1]] = 'P'
        self.grid[self.item_pos[0]][self.item_pos[1]] = 'I'
        self.grid[self.tool_pos[0]][self.tool_pos[1]] = 'T'

    def display(self):
        for row in self.grid:
            print(' '.join(row))
        print()

    def move(self, direction):
        x, y = self.player_pos
        if direction == 'up':
            nx, ny = x - 1, y
        elif direction == 'down':
            nx, ny = x + 1, y
        elif direction == 'left':
            nx, ny = x, y - 1
        elif direction == 'right':
            nx, ny = x, y + 1
        else:
            return False

        if 0 <= nx < self.size and 0 <= ny < self.size:
            if self.grid[nx][ny] == '.':
                self.grid[x][y] = '.'
                self.player_pos = (nx, ny)
                self.grid[nx][ny] = 'P'
                return True
            elif self.grid[nx][ny] == 'I':
                self.grid[nx][ny] = '.'
                self.player_pos = (nx, ny)
                self.grid[nx][ny] = 'P'
                return True
            elif self.grid[nx][ny] == 'T':
                print("You found the tool!")
                self.grid[nx][ny] = '.'
                self.player_pos = (nx, ny)
                self.grid[nx][ny] = 'P'
                return True
        return False

