            seen.add(num)
        return -1

    def count_duplicates(nums):
        count = {}
        for num in nums:
            count[num] = count.get(num, 0) + 1
        for num, cnt in count.items():
            if cnt > 1:
                return num
        return -1

    def cycle_detection(nums):
        slow = nums[0]
        fast = nums[nums[0]]
        while slow != fast:
            slow = nums[slow]
            fast = nums[nums[fast]]
        fast = nums[0]
        while slow != fast:
            slow = nums[slow]
            fast = nums[fast]
        return slow

    nums = list(map(int, input().split()))
    if not nums:
        print(-1)
        return
    if len(nums) > 1:
        if len(set(nums)) < len(nums):
            print(cycle_detection(nums))
        else:
            print(find_duplicate(nums))
    else:
        print(nums[0])

