def find_components(graph, n):
    visited = [False] * n
    components = 0

    for node in range(n):
        if not visited[node]:
            components += 1
            stack = [node]
            visited[node] = True
            while stack:
                current = stack.pop()
                for neighbor in graph[current]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        stack.append(neighbor)
    return components

