def solve(edges):
    import sys
    sys.setrecursionlimit(10000)

    n = len(edges)
    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))

    visited = [False] * n
    def dfs(u):
        if visited[u]:
            return
        visited[u] = True
        for v, w in graph[u]:
            dfs(v)

    # Build component map for strongly connected components
    visited = [False] * n
    comp = [0] * n
    comp_id = 0
    def dfs_comp(u):
        if visited[u]:
            return
        visited[u] = True
        comp[u] = comp_id
        for v, w in graph[u]:
            dfs_comp(v)
    for i in range(n):
        if not visited[i]:
            dfs_comp(i)
            comp_id += 1

    # Build condensation graph (DAG of components)
    comp_graph = [[] for _ in range(comp_id)]
    in_degree = [0] * comp_id
    for u, v, w in edges:
        if comp[u] != comp[v]:
            comp_graph[comp[u]].append((comp[v], w))
            in_degree[comp[v]] += 1

    # Topological sort of condensed graph
    from collections import deque
    topo = []
    q = deque()
    for i in range(comp_id):
        if in_degree[i] == 0:
            q.append(i)
    while q:
        u = q.popleft()
        topo.append(u)
        for v, _ in comp_graph[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                q.append(v)

    # Longest path in DAG (using topological sort)
    dist = [-1] * comp_id
    for u in topo:
        for v, w in comp_graph[u]:
            if dist[v] < dist[u] + w:
                dist[v] = dist[u] + w

    # Map component to node (for final answer)
    comp_to_node = {}
    for i in range(n):
        if comp[i] not in comp_to_node:
            comp_to_node[comp[i]] = i

    # Reconstruct the path if possible
    def reconstruct(start_comp, end_comp):
        if start_comp == end_comp:
            return [comp_to_node[start_comp]]
        for u in topo:
            if comp[u] == start_comp:
                for v, w in comp_graph[u]:
                    if dist[v] == dist[u] + w:
                        path = reconstruct(v, end_comp)
                        if path:
                            return [comp_to_node[start_comp]] + path
        return None

    # Determine start and end components
    start_comp = comp[0]
    end_comp = comp[0]
    for i in range(n):
        if i == n - 1:
            end_comp = comp[i]

    path = reconstruct(start_comp, end_comp)
    if path:
        return len(path) - 1
    return -1

