def solve(graph, start, end):
    if start == end:
        return 0
    visited = set()
    queue = deque()
    queue.append((start, 0))
    visited.add(start)

    while queue:
        node, dist = queue.popleft()
        for neighbor, weight in graph[node]:
            if neighbor == end:
                return dist + weight
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append((neighbor, dist + weight))
    return -1

