        for c in range(cols):
            if maze[r][c] == 'S':
                start = (r, c)
            if maze[r][c] == 'E':
                end = (r, c)

    if not start or not end:
        print()
        return

    visited = set()
    queue = [(start[0], start[1], 0)]
